  },
  'gemini-3-8-flash': {
    name: 'Gemini 3.8 Flash',
    max5h: 150,
    used5h: 18,
    maxWeekly: 1500,
    usedWeekly: 110,
    type: 'google',
    resetHours: 4.8
  },
  'gemini-4-argon': {
    name: 'Gemini 4 Argon',
    max5h: 50,
    used5h: 9,
    maxWeekly: 400,
    usedWeekly: 45,
    type: 'google',
    resetHours: 1.7
  },
  'nvidia-llama-405b': {
    name: 'OSS Llama 3.1 405B',
    max5h: 1000, // NVIDIA Build API Credits
    used5h: 68,
    unit: 'Credits',
    rpmLimit: 40,
    type: 'nvidia',
    resetHours: 24
  },
  'nvidia-nemotron-120b': {
    name: 'OSS Nemotron 120B',
    max5h: 1000,
    used5h: 42,
    unit: 'Credits',
    rpmLimit: 40,
    type: 'nvidia',
    resetHours: 24
  }
};

// 메시지 저장소
let messages = [];

// 모델별 실시간 쿼터 조회 API
app.get('/api/quota', (req, res) => {
  const model = req.query.model || 'claude-3-7-sonnet';
  const q = MODEL_QUOTAS[model] || MODEL_QUOTAS['claude-3-7-sonnet'];

  res.json({
    model,
    name: q.name,
    type: q.type,
    unit: q.unit || '회',
    max5h: q.max5h,
    used5h: q.used5h,
    remaining5h: Math.max(0, q.max5h - q.used5h),
    percent5h: Math.round(((q.max5h - q.used5h) / q.max5h) * 100),
    maxWeekly: q.maxWeekly || null,
    remainingWeekly: q.maxWeekly ? (q.maxWeekly - q.usedWeekly) : null,
    resetInHours: q.resetHours,
    allQuotas: MODEL_QUOTAS
  });
});

// 댓글 피드 목록 조회
